  // =========================================================================
  // PAGE 2 BUILDER: PILING PROGRESS REPORT (With Image 2 LEDGER Table)
  // =========================================================================
  function renderDailyReportPage2() {
    const container = document.getElementById('dr-sheet-2');
    if (!container) return;

    const curDate = DailyReportState.date;
    const pilesDb = window.__PILES_DB__ || [];
    const progressRecs = getProgressRecords();

    let drivenCount = 0;
    let todayCount = 0;
    const todayPilesList = [];

    pilesDb.forEach(p => {
      const rec = progressRecs[p.no];
      if (rec && rec.status === 'driven') {
        if (!rec.date || rec.date <= curDate) {
          drivenCount++;
        }
        if (rec.date === curDate) {
          todayCount++;
          todayPilesList.push({ pile: p, rec: rec });
        }
      }
    });

    const drivenRecords = Object.values(progressRecs).filter(r => r && r.status === 'driven');
    const uniqueDates = [...new Set(drivenRecords.map(r => r.date))].filter(Boolean).sort();
    const projectStartDate = (uniqueDates.length > 0) ? uniqueDates[0] : '2026-10-06';
    
    // Dynamic working schedule (31 baseline days + automatic extension until 93 piles complete)
    const extInfo = getExtendedWorkingScheduleInfo(projectStartDate, curDate);
    const workingDaysSchedule = extInfo.schedule;
    const totalDays = Math.max(31, workingDaysSchedule.length);
    const isExtended = totalDays > 31;

    const elapsedDays = extInfo.elapsedWorkingDays;
    const planCumCount = Math.min(elapsedDays * 3, 93);
    const variance = drivenCount - planCumCount;
    const varianceText = variance > 0 ? `เร็วกว่าแผน +${variance} ต้น` : (variance < 0 ? `ช้ากว่าแผน ${Math.abs(variance)} ต้น` : `ตามแผนงาน (0 ต้น)`);
    const pct = ((drivenCount / 93) * 100).toFixed(1);

    // =========================================================================
    // DYNAMIC HEIGHT SCALING FOR PERFECT FIT ON A4 (Handles 3+ piles & 3+ tiers)
    // =========================================================================
    const effectivePilesCount = Math.max(0, todayCount);
    const extraTiersCount = Math.max(0, Math.ceil(Math.max(0, totalDays - 31) / 16));
    let planContainerH = 300;
    let chartContainerH = 152;

    if (effectivePilesCount >= 3) {
      const extra = effectivePilesCount - 2;
      planContainerH = Math.max(245, 290 - (extra * 7));
      chartContainerH = Math.max(128, 148 - (extra * 4));
    } else if (effectivePilesCount === 2) {
      planContainerH = 292;
      chartContainerH = 150;
    }

    if (extraTiersCount > 0) {
      planContainerH = Math.max(235, planContainerH - (extraTiersCount * 16));
      chartContainerH = Math.max(124, chartContainerH - (extraTiersCount * 10));
    }

    const planCanvasH = planContainerH * 2;
    const chartCanvasH = chartContainerH * 2;

    // =========================================================================
    // BUILD DYNAMIC TIER COMPARISON TABLE (แถวที่ 1-2 ครบ 31 วัน + แถวที่ 3+ อัตโนมัติจนครบ 93 ต้น)
    // =========================================================================
    const allDays = [];
    let runningPlanCum = 0;

    for (let i = 0; i < totalDays; i++) {
      const schedDate = workingDaysSchedule[i] || '';
      const isTodayOrSelected = (schedDate === curDate);
      const isFuture = schedDate ? (schedDate > curDate) : true;
      const isExtendedDay = i >= 31;
      const holidayInfo = getHolidayInfo(schedDate);
      const isHolidayWork = Boolean(holidayInfo);

      const dayPlan = isExtendedDay ? 0 : 3;
      runningPlanCum = isExtendedDay ? 93 : Math.min(93, (i + 1) * 3);

      const dayActual = drivenRecords.filter(r => r.date === schedDate).length;
      const cumActual = drivenRecords.filter(r => r.date && r.date <= schedDate).length;

      allDays.push({
        index: i,
        date: schedDate,
        formattedDate: schedDate ? formatThaiDayMonth(schedDate) : ('D' + (i + 1)),
        isToday: isTodayOrSelected,
        isFuture: isFuture,
        isExtendedDay: isExtendedDay,
        isHolidayWork: isHolidayWork,
        holidayName: holidayInfo ? holidayInfo.name : '',
        dayPlan: dayPlan,
        planCum: runningPlanCum,
        dayActual: dayActual,
        actualCum: cumActual
      });
    }

    function buildDrTierBlock(tierNum, tierTitle, startIdx, endIdx, targetNote, isOverrunTier) {
      let headerCells = '';
      let planCells = '';
      let actualCells = '';
      let cumPlanCells = '';
      let cumActualCells = '';

      const cellPadCls = isExtended ? 'px-0.5 py-[1px]' : 'p-0.5';

      for (let i = startIdx; i < endIdx; i++) {
        const d = allDays[i];
        if (!d) continue;

        const isAct = d.isToday;
        const colClass = isAct ? 'active-col' : '';

        let headerInner = '';
        if (isAct) {
          headerInner = `<span class="font-black text-[#9a3412]">${d.formattedDate}</span>`;
          if (d.isHolidayWork) {
            headerInner += `<span class="block text-[7px] text-amber-900 font-extrabold leading-tight">วันหยุด</span>`;
          }
        } else if (d.isHolidayWork) {
          headerInner = `<span class="font-black text-rose-700">${d.formattedDate}</span><span class="block text-[7px] text-rose-600 font-extrabold leading-tight">วันหยุด</span>`;
        } else {
          headerInner = `<span class="font-bold text-[#1d2b45]">${d.formattedDate}</span>`;
        }

        const holidayTooltip = d.isHolidayWork ? ` (${d.holidayName || 'ทำงานวันหยุด'})` : '';
        headerCells += `
          <th class="${cellPadCls} border border-slate-700 text-center select-none cursor-pointer transition-colors ${colClass}" title="คลิกเพื่อดูรายงานวันที่ ${d.date}${holidayTooltip}" onclick="handleDrDateSelect('${d.date}')">
            ${headerInner}
          </th>
        `;

        planCells += `
          <td class="${cellPadCls} border border-slate-700 font-mono text-center text-[#3e4b69] text-[8px] sm:text-[8.5px] ${colClass}">
            ${d.isExtendedDay ? '<span class="text-slate-400">-</span>' : d.dayPlan}
          </td>
        `;

        const actDisplay = d.isFuture ? '-' : d.dayActual;
        actualCells += `
          <td class="${cellPadCls} border border-slate-700 font-mono text-center font-black text-[#1d2b45] text-[8px] sm:text-[8.5px] ${colClass}">
            ${actDisplay}
          </td>
        `;

        cumPlanCells += `
          <td class="${cellPadCls} border border-slate-700 font-mono text-center font-extrabold text-[#1d2b45] text-[8px] sm:text-[8.5px] ${colClass}">
            ${d.planCum}
          </td>
        `;

        const cumActDisplay = d.isFuture ? '-' : d.actualCum;
        cumActualCells += `
          <td class="${cellPadCls} border border-slate-700 font-mono text-center font-black text-[#064e3b] text-[8px] sm:text-[8.5px] ${colClass}">
            ${cumActDisplay}
          </td>
        `;
      }

      const headBg = isOverrunTier ? 'bg-[#fff3e0]' : 'bg-[#f6e9d7]';
      const badgeCls = isOverrunTier
        ? 'px-1.5 py-0.2 bg-[#ea580c] text-white border border-slate-900 rounded-none text-[8px] font-black'
        : 'px-1.5 py-0.2 bg-[#1d2b45] text-[#f7b844] rounded-none text-[8px] font-black';

      return `
        <div class="border-1.5 border-[#1d2b45] bg-white overflow-hidden rounded-none shadow-[1.5px_1.5px_0px_#1d2b45]">
          <div class="px-2 py-[1.5px] ${headBg} border-b-1.5 border-[#1d2b45] flex items-center justify-between text-[8.5px] font-bold leading-tight">
            <div class="flex items-center gap-1.5">
              <span class="${badgeCls}">${tierNum}</span>
              <span class="text-[#1d2b45] font-black">${tierTitle}</span>
            </div>
            <span class="text-[8px] text-[#3e4b69] font-mono font-bold">${targetNote}</span>
          </div>
          <table class="piling-daily-table w-full text-center border-collapse text-[8px] sm:text-[8.5px] leading-none table-fixed">
            <thead>
              <tr class="bg-white border-b border-slate-700">
                <th class="${cellPadCls} border border-slate-700 font-black text-left text-[#1d2b45] whitespace-nowrap pl-1 text-[8px]" style="width: 58px;">วันที่</th>
                ${headerCells}
              </tr>
            </thead>
            <tbody>
              <tr class="row-plan bg-white">
                <td class="${cellPadCls} border border-slate-700 text-left font-bold text-[#3e4b69] whitespace-nowrap pl-1 text-[8px]">แผนรายวัน</td>
                ${planCells}
              </tr>
              <tr class="row-actual bg-[#f8fafc]">
                <td class="${cellPadCls} border border-slate-700 text-left font-black text-[#1d2b45] whitespace-nowrap pl-1 text-[8px]">ผลงานจริง</td>
                ${actualCells}
              </tr>
              <tr class="row-accum-plan bg-[#f1f5f9]">
                <td class="${cellPadCls} border border-slate-700 text-left font-extrabold text-[#1d2b45] whitespace-nowrap pl-1 text-[8px]">แผนสะสม</td>
                ${cumPlanCells}
              </tr>
              <tr class="row-accum-actual bg-[#ecfdf5]">
                <td class="${cellPadCls} border border-slate-700 text-left font-black text-[#064e3b] whitespace-nowrap pl-1 text-[8px]">ผลงานสะสม</td>
                ${cumActualCells}
              </tr>
            </tbody>
          </table>
        </div>
      `;
    }

    const tierDefinitions = [
      { start: 0, end: 16, num: 'แถวที่ 1', note: 'เป้าหมายสะสมงวดนี้ 48 ต้น', overrun: false },
      { start: 16, end: 31, num: 'แถวที่ 2', note: isExtended ? 'เป้าหมายตามแผนเดิม 93 ต้น (ครบกำหนด 31 วัน)' : 'เป้าหมายงานเสาเข็มครบ 93 ต้น', overrun: false }
    ];

    let nextTierStart = 31;
    let tierNumCounter = 3;
    while (nextTierStart < totalDays) {
      const nextTierEnd = Math.min(totalDays, nextTierStart + 16);
      const remPiles = Math.max(0, 93 - drivenCount);
      const rightNote = remPiles > 0
        ? `จนครบ 93 ต้น (สะสม ${drivenCount}/93 · เหลือ ${remPiles} ต้น)`
        : `กดครบ 93 ต้นแล้ว (สะสม 93/93 ต้น)`;
      tierDefinitions.push({
        start: nextTierStart,
        end: nextTierEnd,
        num: `แถวที่ ${tierNumCounter}`,
        note: rightNote,
        overrun: true
      });
      nextTierStart = nextTierEnd;
      tierNumCounter++;
    }

    const allTiersHtml = tierDefinitions.map(td => {
      const sLabel = workingDaysSchedule[td.start] ? formatThaiDayMonth(workingDaysSchedule[td.start]) : `D${td.start + 1}`;
      const eLabel = workingDaysSchedule[td.end - 1] ? formatThaiDayMonth(workingDaysSchedule[td.end - 1]) : `D${td.end}`;
      const rangeTitle = td.overrun
        ? `วันทำการที่ ${td.start + 1} – ${td.end} (${sLabel} – ${eLabel}) · ช่วงเร่งรัดหลังครบกำหนดแผน`
        : `วันทำการที่ ${td.start + 1} – ${td.end} (${sLabel} – ${eLabel})`;
      return buildDrTierBlock(td.num, rangeTitle, td.start, td.end, td.note, td.overrun);
    }).join('');
    const ledgerSubnoteText = isExtended
      ? `· ${tierDefinitions.length} แถว · แผน 31 วัน + ขยายถึง D${totalDays} (จนครบ 93 ต้น)`
      : `· 2 แถว ครบ 31 วันทำการ`;

    // Build Today's Pressed Piles Log Rows
    let pilesLogRows = '';
    if (todayPilesList.length === 0) {
      pilesLogRows = `
        <tr style="height: 20px;">
          <td colspan="12" class="p-1 text-center text-slate-500 italic border border-slate-700 text-[9px]">
            ไม่มีรายการเสาเข็มที่กดในวันที่รายงาน (${curDate})
          </td>
        </tr>
      `;
    } else {
      todayPilesList.forEach((item, idx) => {
        const p = item.pile;
        const r = item.rec || {};

        // รหัสเสาเข็ม
        const pileId = p.tag || (p.no ? ('P' + String(p.no).padStart(2, '0')) : (p.name || '-'));

        // พิกัดแบบ N, E
        const nVal = (p.northing !== undefined && p.northing !== null && !isNaN(Number(p.northing))) ? Number(p.northing) : null;
        const eVal = (p.easting !== undefined && p.easting !== null && !isNaN(Number(p.easting))) ? Number(p.easting) : null;
        const targetN = nVal !== null ? nVal.toFixed(3) : '-';
        const targetE = eVal !== null ? eVal.toFixed(3) : '-';
        const targetCoStr = (nVal !== null && eVal !== null) ? `${targetN}, ${targetE}` : '-';

        // พิกัดจริงหลังกด n, e
        const hasActualN = r && r.actual_n !== undefined && r.actual_n !== null && String(r.actual_n).trim() !== '' && !isNaN(parseFloat(r.actual_n));
        const hasActualE = r && r.actual_e !== undefined && r.actual_e !== null && String(r.actual_e).trim() !== '' && !isNaN(parseFloat(r.actual_e));
        const actN = hasActualN ? parseFloat(r.actual_n) : null;
        const actE = hasActualE ? parseFloat(r.actual_e) : null;
        const actualN = actN !== null ? actN.toFixed(3) : '-';
        const actualE = actE !== null ? actE.toFixed(3) : '-';
        const actualCoStr = (actN !== null && actE !== null) ? `${actualN}, ${actualE}` : '-';

        // ผลต่างพิกัด Δn, Δe
        let dn = '-', de = '-';
        if (actN !== null && nVal !== null) {
          const diffN = actN - nVal;
          dn = (diffN >= 0 ? '+' : '') + diffN.toFixed(3);
        }
        if (actE !== null && eVal !== null) {
          const diffE = actE - eVal;
          de = (diffE >= 0 ? '+' : '') + diffE.toFixed(3);
        }
        const diffCoStr = (dn !== '-' || de !== '-') ? `${dn}, ${de}` : '-';

        // ระดับ PCO (แบบ)
        const pcoVal = (p.pco_level !== undefined && p.pco_level !== null) ? Number(p.pco_level) : ((p.co_level !== undefined && p.co_level !== null) ? Number(p.co_level) : null);
        const pco = (pcoVal !== null && !isNaN(pcoVal)) ? pcoVal.toFixed(3) : '-';

        // ระดับ TOP จริง และผลต่าง
        const hasActualTop = r && r.actual_top !== undefined && r.actual_top !== null && String(r.actual_top).trim() !== '' && !isNaN(parseFloat(r.actual_top));
        const actTopVal = hasActualTop ? parseFloat(r.actual_top) : (pcoVal !== null ? pcoVal : null);
        const actualTop = actTopVal !== null ? actTopVal.toFixed(3) : '-';

        let diffTop = '-';
        if (actTopVal !== null && pcoVal !== null) {
          const dt = actTopVal - pcoVal;
          diffTop = (dt >= 0 ? '+' : '') + dt.toFixed(3);
        }

        pilesLogRows += `
          <tr class="text-[8px] leading-tight" style="height: 16px;">
            <td class="border border-slate-700 px-1 py-[1px] text-center font-mono whitespace-nowrap">${idx + 1}</td>
            <td class="border border-slate-700 px-1 py-[1px] font-bold text-center text-slate-900 whitespace-nowrap">${pileId}</td>
            <td class="border border-slate-700 px-1 py-[1px] text-center whitespace-nowrap">${p.footing || '-'}</td>
            <td class="border border-slate-700 px-1 py-[1px] text-center font-mono whitespace-nowrap">${p.grid || '-'}</td>
            <td class="border border-slate-700 px-1 py-[1px] text-right font-mono text-[7.5px] whitespace-nowrap">${targetCoStr}</td>
            <td class="border border-slate-700 px-1 py-[1px] text-right font-mono text-[7.5px] font-bold text-emerald-800 whitespace-nowrap">${actualCoStr}</td>
            <td class="border border-slate-700 px-1 py-[1px] text-center font-mono text-[7.5px] whitespace-nowrap">${diffCoStr}</td>
            <td class="border border-slate-700 px-1 py-[1px] text-right font-mono text-[8px] whitespace-nowrap">${pco}</td>
            <td class="border border-slate-700 px-1 py-[1px] text-right font-mono text-[8px] font-bold whitespace-nowrap">${actualTop}</td>
            <td class="border border-slate-700 px-1 py-[1px] text-center font-mono text-[8px] whitespace-nowrap">${diffTop}</td>
            <td class="border border-slate-700 px-1 py-[1px] text-center text-[8px] whitespace-nowrap">${p.type || 'I-0.40m'}</td>
            <td class="border border-slate-700 px-1 py-[1px] text-center font-mono text-[8px] whitespace-nowrap">${r.date || curDate}</td>
          </tr>
        `;
      });
    }

    container.innerHTML = `
      <!-- Header: Clean Rectangular Frame (Monochrome) -->
      <div class="border-2 border-black px-2 py-1 mb-1 bg-white">
        <div class="flex items-center justify-between">
          <div>
            <div class="text-[9.5px] font-bold text-slate-800 leading-tight">โครงการ PYNN PRIDI 37 (ซอยปรีดี พนมยงค์ 37)</div>
            <h2 class="text-xs sm:text-[13px] font-black text-black leading-tight">รายงานความคืบหน้างานเสาเข็ม (Piling Progress Report)</h2>
          </div>
          <div class="text-right leading-tight">
            <div class="text-[10.5px] font-bold text-slate-800">วันที่รายงาน : <span class="font-mono font-black">${curDate}</span></div>
            <div class="text-[9px] text-slate-600 font-mono">เสาเข็ม I-40 รวม 93 ต้น</div>
          </div>
        </div>
      </div>

      <!-- KPI Summary Table: Simple Rectangular B&W Grid -->
      <table class="w-full border-collapse border border-black text-[9.5px] text-center font-bold mb-1 bg-white">
        <thead>
          <tr class="bg-slate-100">
            <th class="border border-black py-0.5 px-1 w-1/4">แผนวันนี้ / กดแล้ว</th>
            <th class="border border-black py-0.5 px-1 w-1/4">แผนสะสม (${elapsedDays}/31 วัน${elapsedDays > 31 ? ` · เลยแผน +${elapsedDays - 31} วัน` : ''})</th>
            <th class="border border-black py-0.5 px-1 w-1/4">กดจริงสะสม</th>
            <th class="border border-black py-0.5 px-1 w-1/4">สถานะเทียบแผนงาน</th>
          </tr>
        </thead>
        <tbody>
          <tr>
            <td class="border border-black py-0.5 px-1 font-mono text-[10.5px]">
              แผน 3 ต้น | <span class="font-black text-black">กดแล้ว ${todayCount} ต้น</span>
            </td>
            <td class="border border-black py-0.5 px-1 font-mono text-[10.5px]">
              <span class="font-black text-black">${planCumCount}</span> ต้น
            </td>
            <td class="border border-black py-0.5 px-1 font-mono text-[10.5px]">
              <span class="font-black text-black">${drivenCount}/93</span> (${pct}%)
            </td>
            <td class="border border-black py-0.5 px-1 font-mono text-[10.5px] font-black">
              ${varianceText}
            </td>
          </tr>
        </tbody>
      </table>

      <!-- Piling Progress Plan Snapshot (Dynamic Height Auto-Fit) -->
      <div class="border border-black mb-1 bg-white">
        <div class="bg-slate-100 border-b border-black px-2 py-0.5 flex items-center justify-between text-[9.5px] font-black">
          <span>แผนผังความคืบหน้างานเสาเข็ม (Piling Progress Plan)</span>
          <div class="flex items-center gap-3 text-[9px]">
            <span class="inline-flex items-center gap-1 font-bold text-sky-700">
              <svg class="w-2.5 h-2.5 inline-block shrink-0" viewBox="0 0 12 12" width="10" height="10">
                <circle cx="6" cy="6" r="5" fill="#0284c7" stroke="#0369a1" stroke-width="1.2" />
              </svg>
              <span>กดวันนี้</span>
            </span>
            <span class="inline-flex items-center gap-1 font-bold text-emerald-800">
              <svg class="w-2.5 h-2.5 inline-block shrink-0" viewBox="0 0 12 12" width="10" height="10">
                <circle cx="6" cy="6" r="5" fill="#10b981" stroke="#047857" stroke-width="1.2" />
              </svg>
              <span>กดแล้ว</span>
            </span>
            <span class="inline-flex items-center gap-1 font-bold text-slate-800">
              <svg class="w-2.5 h-2.5 inline-block shrink-0" viewBox="0 0 12 12" width="10" height="10">
                <circle cx="6" cy="6" r="5" fill="#ffffff" stroke="#1e293b" stroke-width="1.2" />
              </svg>
              <span>รอกด</span>
            </span>
          </div>
        </div>
        <div class="p-0.5 flex items-center justify-center bg-white overflow-hidden" style="height: ${planContainerH}px;">
          <canvas id="drPlanCanvas" class="w-full h-full block" width="1440" height="${planCanvasH}"></canvas>
        </div>
      </div>

      <!-- S-Curve Progress Graph (Dynamic Height Auto-Fit) -->
      <div class="border border-slate-700 rounded-sm overflow-hidden mb-1 bg-white shadow-xs">
        <div class="bg-slate-100 border-b border-slate-700 px-2 py-0.5 flex items-center justify-between text-[9.5px] font-black">
          <span class="text-slate-900">กราฟความคืบหน้าสะสมงานเสาเข็ม (Accumulated Progress S-Curve: Plan vs Actual)</span>
          <span class="text-[8.5px] text-slate-600 font-normal">เกณฑ์แผนงาน 3 ต้น/วันทำการ (รวม 93 ต้น)</span>
        </div>
        <div class="p-0.5 flex items-center justify-center bg-white" style="height: ${chartContainerH}px;">
          <canvas id="drProgressChartCanvas" class="w-full h-full block" width="1160" height="${chartCanvasH}"></canvas>
        </div>
      </div>

      <!-- DYNAMIC COMPARISON TABLE: Plan 3 ต้น/วันทำการ vs Actual (ขยายแถวอัตโนมัติจนครบ 93 ต้น) -->
      <div class="border-2 border-slate-900 rounded-none overflow-hidden mb-1 bg-white shadow-[2px_2px_0px_#0f172a]">
        <div class="bg-white px-2 py-[2px] border-b-2 border-slate-900 flex items-center justify-between">
          <div class="flex items-center gap-1.5">
            <span class="w-3.5 h-3.5 rounded-none bg-[#ea580c] text-white flex items-center justify-center text-[8px] font-black shadow-[1px_1px_0px_#0f172a]">
              <i data-lucide="table" class="w-2.5 h-2.5"></i>
            </span>
            <h3 class="text-[9.5px] font-black text-slate-900">ตารางเปรียบเทียบแผนงานรายวันและสะสม (Plan 3 ต้น/วันทำการ vs Actual)</h3>
          </div>
          <span class="text-[8.5px] font-mono text-slate-500">${ledgerSubnoteText}</span>
        </div>
        <div class="p-0.5 ${isExtended ? 'space-y-0.5' : 'space-y-1'}">
          ${allTiersHtml}
        </div>
      </div>

      <!-- Today's Pressed Piles Log Table -->
      <div class="border-2 border-slate-900 rounded-none overflow-hidden bg-white shadow-[2px_2px_0px_#0f172a]">
        <div class="bg-slate-100 border-b-2 border-slate-900 px-2 py-[2px] text-[9.5px] font-bold flex justify-between items-center">
          <span class="text-slate-900 font-black">รายการเสาเข็มที่กดในวันที่รายงาน (Daily Pressed Piles Log)</span>
          <span class="font-mono font-black text-slate-900 bg-white px-2 py-[1px] border border-slate-900 shadow-[1px_1px_0px_#0f172a]">${todayCount} ต้น</span>
        </div>
        <div class="overflow-x-auto">
          <table class="dr-piling-table w-full text-center border-collapse">
            <thead>
              <tr class="bg-slate-50 text-[8px] whitespace-nowrap">
                <th class="w-5 py-0.5 px-1">No.</th>
                <th class="py-0.5 px-1">รหัสเข็ม</th>
                <th class="py-0.5 px-1">ฐานราก</th>
                <th class="py-0.5 px-1">กริด</th>
                <th class="py-0.5 px-1">Co (N, E) แบบ (m)</th>
                <th class="py-0.5 px-1">Co (n, e) หลังกด (m)</th>
                <th class="py-0.5 px-1">ผลต่าง (Δn, Δe)</th>
                <th class="py-0.5 px-1">ระดับ PCO</th>
                <th class="py-0.5 px-1">ระดับ TOP จริง</th>
                <th class="py-0.5 px-1">ผลต่าง (ม.)</th>
                <th class="py-0.5 px-1">ชนิดเข็ม</th>
                <th class="py-0.5 px-1">วันที่กด</th>
              </tr>
            </thead>
            <tbody>
              ${pilesLogRows}
            </tbody>
          </table>
        </div>
      </div>
    `;

    setTimeout(() => {
      renderDailyPilingPlanMonochrome();
      renderDailyProgressChart();
      if (window.lucide) window.lucide.createIcons();
    }, 60);
  }

  
  // Handle Date Selection from 2-Tier Comparison Table or elsewhere
  window.handleDrDateSelect = function (dateStr) {
    if (!dateStr) return;
    DailyReportState.date = dateStr;
    const dateInput = document.getElementById('inp-report-date') || document.getElementById('report-date-picker') || document.getElementById('date-picker');
    if (dateInput) dateInput.value = dateStr;
    DailyReportState.tasks = generateAutomaticTasksList(dateStr);
    renderDailyReportPage1();
    renderDailyReportPage2();
    showDrToast('📅 สลับดูรายงานวันที่ ' + formatThaiDayMonth(dateStr) + ' (' + dateStr + ')', 'info');
  };

  // Render S-Curve Progress Chart onto drProgressChartCanvas (มีเส้นและมีจุดเหมือนในเว็บ ขยายขนาดเต็มพื้นที่)
  function renderDailyProgressChart() {
    const canvas = document.getElementById('drProgressChartCanvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const w = canvas.width || 1160;
    const h = canvas.height || 460;

    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, w, h);

    const padL = 55, padR = 25;
    const padT = h < 320 ? 28 : 36;
    const padB = h < 320 ? 32 : 40;
    const legY = h < 320 ? 12 : 14;
    const plotW = w - padL - padR;
    const plotH = h - padT - padB;
    const maxY = 95;

    const curDate = DailyReportState.date;
    const progressRecs = getProgressRecords();
    const drivenRecords = Object.values(progressRecs).filter(r => r && r.status === 'driven');
    const uniqueDates = [...new Set(drivenRecords.map(r => r.date))].filter(Boolean).sort();
    const projectStartDate = (uniqueDates.length > 0) ? uniqueDates[0] : '2026-10-06';
    const extInfo = getExtendedWorkingScheduleInfo(projectStartDate, curDate);
    const schedule = extInfo.schedule;

    // Plan array: [3, 6, 9, ..., 93, 93, ...]
    const planData = schedule.map((_, idx) => Math.min(93, (idx + 1) * 3));

    // Actual array up to curDate
    const actualData = [];
    for (let i = 0; i < schedule.length; i++) {
      const sDate = schedule[i];
      if (sDate <= curDate) {
        const count = drivenRecords.filter(r => r.date && r.date <= sDate).length;
        actualData.push(count);
      } else {
        break;
      }
    }

    // Y-Grid & Labels (เส้นตารางแนวนอน)
    ctx.font = 'bold 11.5px Montserrat, Sarabun, sans-serif';
    ctx.textAlign = 'right';
    ctx.textBaseline = 'middle';
    for (let yVal = 0; yVal <= 90; yVal += 15) {
      const py = padT + plotH - (yVal / maxY) * plotH;
      ctx.strokeStyle = '#e2e8f0';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(padL, py);
      ctx.lineTo(w - padR, py);
      ctx.stroke();

      ctx.fillStyle = '#475569';
      ctx.fillText(yVal + ' ต้น', padL - 8, py);
    }

    // X-Axis Grid & Labels (วันทำการ D1, D5, D10, D15, D20, D25, D31 และช่วงขยาย D32+ ถึงวันสุดท้าย)
    ctx.font = 'bold 10px Montserrat, Sarabun, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';

    const markedSet = new Set([0, 4, 9, 14, 19, 24, 30]);
    if (schedule.length > 31) {
      const lastSchedIdx = schedule.length - 1;
      for (let m = 34; m <= lastSchedIdx - 4; m += 5) {
        markedSet.add(m);
      }
      if (lastSchedIdx - 30 >= 4) {
        markedSet.add(lastSchedIdx);
      }
      const curIdx = actualData.length - 1;
      if (curIdx > 30 && Math.abs(curIdx - 30) >= 4 && Math.abs(curIdx - lastSchedIdx) >= 4) {
        markedSet.add(curIdx);
      }
    }
    const markedIndices = [...markedSet].filter(idx => idx >= 0 && idx < schedule.length).sort((a, b) => a - b);
    markedIndices.forEach(idx => {
      if (idx < schedule.length) {
        const px = padL + (idx / Math.max(1, schedule.length - 1)) * plotW;
        ctx.strokeStyle = '#f1f5f9';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(px, padT);
        ctx.lineTo(px, padT + plotH);
        ctx.stroke();

        ctx.fillStyle = '#64748b';
        ctx.fillText('D' + (idx + 1), px, padT + plotH + (h < 320 ? 4 : 5));

        // วันที่แบบย่อ
        const sDate = schedule[idx];
        const sParts = sDate.split('-');
        if (sParts.length === 3) {
          ctx.fillStyle = '#94a3b8';
          ctx.font = '9px Montserrat, Sarabun, sans-serif';
          ctx.fillText(parseInt(sParts[2], 10) + '/' + parseInt(sParts[1], 10), px, padT + plotH + (h < 320 ? 16 : 18));
          ctx.font = 'bold 10px Montserrat, Sarabun, sans-serif';
        }
      }
    });

    // 1. Plan Line (เส้นประสีส้ม/แดง พร้อมจุดกลมสีส้มทุกวันทำการ D1..D31 เหมือนในเว็บ)
    ctx.strokeStyle = '#ed6845';
    ctx.lineWidth = 2.6;
    ctx.setLineDash([6, 4]);
    ctx.beginPath();
    for (let i = 0; i < planData.length; i++) {
      const px = padL + (i / (planData.length - 1)) * plotW;
      const py = padT + plotH - (planData[i] / maxY) * plotH;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.stroke();
    ctx.setLineDash([]);

    // วาดจุดกลมสีส้มบนเส้นแผนงาน
    for (let i = 0; i < planData.length; i++) {
      const px = padL + (i / (planData.length - 1)) * plotW;
      const py = padT + plotH - (planData[i] / maxY) * plotH;
      ctx.fillStyle = '#ed6845';
      ctx.beginPath();
      ctx.arc(px, py, 3, 0, Math.PI * 2);
      ctx.fill();
    }

    // 2. Actual Line with Fill & Points (เส้นทึบสีเขียวพร้อมแถบสีโปร่งแสงและจุดกลมสีเขียวขอบเข้ม เหมือนในเว็บ)
    if (actualData.length > 0) {
      // Area Fill
      ctx.beginPath();
      for (let i = 0; i < actualData.length; i++) {
        const px = padL + (i / (planData.length - 1)) * plotW;
        const py = padT + plotH - (actualData[i] / maxY) * plotH;
        if (i === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      }
      const lastPx = padL + ((actualData.length - 1) / (planData.length - 1)) * plotW;
      ctx.lineTo(lastPx, padT + plotH);
      ctx.lineTo(padL, padT + plotH);
      ctx.closePath();
      ctx.fillStyle = 'rgba(16, 185, 129, 0.18)';
      ctx.fill();

      // Solid emerald line
      ctx.strokeStyle = '#10b981';
      ctx.lineWidth = 3.6;
      ctx.beginPath();
      for (let i = 0; i < actualData.length; i++) {
        const px = padL + (i / (planData.length - 1)) * plotW;
        const py = padT + plotH - (actualData[i] / maxY) * plotH;
        if (i === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      }
      ctx.stroke();

      // วาดจุดกลมสีเขียวขอบเข้มทุกจุดผลงานจริง
      for (let i = 0; i < actualData.length; i++) {
        const px = padL + (i / (planData.length - 1)) * plotW;
        const py = padT + plotH - (actualData[i] / maxY) * plotH;
        ctx.fillStyle = '#10b981';
        ctx.beginPath();
        ctx.arc(px, py, 4.5, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = '#064e3b';
        ctx.lineWidth = 1.6;
        ctx.stroke();
      }

      // จุดวันปัจจุบัน (Current Day Pulse Highlight) พร้อมป้ายแสดงยอดสะสม
      const curIdx = actualData.length - 1;
      const curPx = padL + (curIdx / (planData.length - 1)) * plotW;
      const curPy = padT + plotH - (actualData[curIdx] / maxY) * plotH;

      ctx.fillStyle = '#0284c7';
      ctx.beginPath();
      ctx.arc(curPx, curPy, 7, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 2.5;
      ctx.stroke();

      // Badge ป้ายบอกยอดสะสม
      const labelText = actualData[curIdx] + ' ต้น';
      ctx.font = 'bold 11px Montserrat, Sarabun, sans-serif';
      const badgeW = ctx.measureText(labelText).width + 12;
      const badgeH = 18;
      const badgeX = curPx - badgeW / 2;
      let badgeY = curPy - 24;
      if (badgeY < (padT - 6)) badgeY = curPy + 10;

      ctx.fillStyle = '#0f172a';
      ctx.beginPath();
      ctx.roundRect ? ctx.roundRect(badgeX, badgeY, badgeW, badgeH, 4) : ctx.rect(badgeX, badgeY, badgeW, badgeH);
      ctx.fill();

      ctx.fillStyle = '#ffffff';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(labelText, curPx, badgeY + badgeH / 2);
    }

    // แถบคำอธิบาย Legend ด้านบน (สอดคล้องกับในเว็บ)
    ctx.font = 'bold 11.5px Sarabun, Montserrat, sans-serif';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';

    // 1. Plan Legend (เส้นประ + จุดส้ม)
    ctx.strokeStyle = '#ed6845';
    ctx.lineWidth = 2.6;
    ctx.setLineDash([5, 3]);
    ctx.beginPath();
    ctx.moveTo(padL + 15, legY);
    ctx.lineTo(padL + 35, legY);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = '#ed6845';
    ctx.beginPath();
    ctx.arc(padL + 25, legY, 3, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#334155';
    ctx.fillText('แผนงานสะสม (3 ต้น/วันทำการ)', padL + 42, legY);

    // 2. Actual Legend (เส้นทึบเขียว + จุดเขียว)
    ctx.strokeStyle = '#10b981';
    ctx.lineWidth = 3.2;
    ctx.beginPath();
    ctx.moveTo(padL + 220, legY);
    ctx.lineTo(padL + 245, legY);
    ctx.stroke();
    ctx.fillStyle = '#10b981';
    ctx.beginPath();
    ctx.arc(padL + 232, legY, 4, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#064e3b';
    ctx.lineWidth = 1.4;
    ctx.stroke();

    ctx.fillStyle = '#334155';
    ctx.fillText('ผลงานจริงสะสม (Actual)', padL + 252, legY);

    // 3. Current Day Legend (จุดฟ้า)
    ctx.fillStyle = '#0284c7';
    ctx.beginPath();
    ctx.arc(padL + 415, legY, 5, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 1.5;
    ctx.stroke();

    ctx.fillStyle = '#0369a1';
    ctx.fillText('วันที่รายงานปัจจุบัน', padL + 426, legY);
  }

  // Draw Architectural Plan onto drPlanCanvas (Exactly matches Image 2)
  function renderDailyPilingPlanMonochrome() {
    const canvas = document.getElementById('drPlanCanvas');
    if (!canvas) return;
    const parent = canvas.parentElement;
    const targetW = (parent && parent.clientWidth > 100) ? Math.round(parent.clientWidth * 2) : (canvas.width || 1440);
    const targetH = (parent && parent.clientHeight > 60) ? Math.round(parent.clientHeight * 2) : (canvas.height || 474);
    if (canvas.width !== targetW || canvas.height !== targetH) {
      canvas.width = targetW;
      canvas.height = targetH;
    }
    const ctx = canvas.getContext('2d');
    const w = canvas.width;
    const h = canvas.height;

    // Crisp white background
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, w, h);

    // 1. Direct WebGL Top-Down Render if available
    if (window.currentModel && window.renderer && window.orthoCamera && window.scene) {
      try {
        const prevSize = new THREE.Vector2();
        window.renderer.getSize(prevSize);
        const prevRatio = window.renderer.getPixelRatio();
        const prevCam = window.activeCamera;

        window.renderer.setSize(w, h, false);
        window.renderer.setPixelRatio(1);

        const centerX = 16.90;
        const centerY = 8.05;
        const spanX = 45.2;
        const spanY = 22.8;
        const canvasAspect = w / h;
        let camW, camH;
        if (canvasAspect > spanX / spanY) {
          camH = spanY;
          camW = spanY * canvasAspect;
        } else {
          camW = spanX;
          camH = spanX / canvasAspect;
        }

        window.orthoCamera.left = -camW / 2;
        window.orthoCamera.right = camW / 2;
        window.orthoCamera.top = camH / 2;
        window.orthoCamera.bottom = -camH / 2;
        window.orthoCamera.updateProjectionMatrix();
        window.orthoCamera.position.set(centerX, centerY, 80);
        window.orthoCamera.up.set(0, 1, 0);
        window.orthoCamera.lookAt(centerX, centerY, 0);

        if (typeof window.updatePileMeshVisuals === 'function') window.updatePileMeshVisuals();
        window.renderer.render(window.scene, window.orthoCamera);

        ctx.clearRect(0, 0, w, h);
        ctx.drawImage(window.renderer.domElement, 0, 0, w, h);

        window.renderer.setSize(prevSize.x, prevSize.y, false);
        window.renderer.setPixelRatio(prevRatio);
        if (prevCam) window.activeCamera = prevCam;
        return;
      } catch (err) {
        console.warn('3D top-down snapshot error, falling back to 2D vector CAD:', err);
      }
    }

    // 2. High-Precision 2D CAD Blueprint Vector Render (Image 2)
    const minX = -5.2, maxX = 40.0;
    const minY = -3.35, maxY = 19.35;
    const spanX = maxX - minX;
    const spanY = maxY - minY;

    const padX = 12;
    const padY = 8;
    const availW = Math.max(80, w - padX * 2);
    const availH = Math.max(80, h - padY * 2);
    const scale = Math.min(availW / spanX, availH / spanY);

    const drawW = spanX * scale;
    const drawH = spanY * scale;
    const offsetX = padX + (availW - drawW) / 2;
    const offsetY = padY + (availH - drawH) / 2;

    const mapX = (x) => offsetX + (x - minX) * scale;
    const mapY = (y) => h - (offsetY + (y - minY) * scale); // North UP!

    // 1. Draw Property Boundary Line (เส้นขอบเขตที่ดินสีแดงขีดประ)
    const boundaryPolygon = [
      [-2.596, 17.223],
      [36.546, 16.713],
      [37.852, -2.495],
      [-4.060, -2.495]
    ];

    ctx.save();
    ctx.strokeStyle = '#dc2626';
    ctx.lineWidth = Math.max(1.6, scale * 0.08);
    ctx.setLineDash([8, 5]);
    ctx.beginPath();
    boundaryPolygon.forEach(([bx, by], idx) => {
      const px = mapX(bx);
      const py = mapY(by);
      if (idx === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    });
    ctx.closePath();
    ctx.stroke();
    ctx.restore();

    // Boundary Pins Circles & Labels (หมุดรังวัดสีแดง)
    const pins = [
      { label: 'n114250', x: -2.596, y: 17.223, dx: -8, dy: -6, align: 'right' },
      { label: 'n117402', x: 36.546, y: 16.713, dx: 8, dy: -6, align: 'left' },
      { label: 'n115372', x: 37.852, y: -2.495, dx: 8, dy: 3, align: 'left' },
      { label: 'n115816', x: 4.490, y: -2.495, dx: 0, dy: 14, align: 'center' },
      { label: 'ปร', x: -4.060, y: -2.495, dx: -8, dy: 3, align: 'right' }
    ];

    const pinRadius = Math.max(3.8, Math.min(5.2, scale * 0.2));
    pins.forEach(pin => {
      const px = mapX(pin.x);
      const py = mapY(pin.y);

      ctx.fillStyle = '#dc2626';
      ctx.beginPath();
      ctx.arc(px, py, pinRadius, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = '#991b1b';
      ctx.font = `bold ${Math.max(9, Math.min(11, scale * 0.44))}px Montserrat, Sarabun, sans-serif`;
      ctx.textAlign = pin.align;
      ctx.textBaseline = 'middle';
      ctx.fillText(pin.label, px + pin.dx, py + pin.dy);
    });

    // Property Boundary Dimension Labels (ระยะขอบเขตที่ดินทั้ง 4 ด้านตามภาพ 2)
    ctx.fillStyle = '#dc2626';
    ctx.strokeStyle = '#dc2626';
    ctx.lineWidth = 0.8;
    ctx.font = `bold ${Math.max(11, Math.min(14.5, scale * 0.58))}px Arial, Tahoma, Montserrat, Sarabun, sans-serif`;

    // Top: 39.15 m
    ctx.textAlign = 'center';
    ctx.textBaseline = 'bottom';
    ctx.strokeText('39.15 m', mapX(17.0), mapY(17.1) - 6);
    ctx.fillText('39.15 m', mapX(17.0), mapY(17.1) - 6);

    // Bottom: 41.91 m
    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';
    ctx.strokeText('41.91 m', mapX(18.0), mapY(-2.55) + 6);
    ctx.fillText('41.91 m', mapX(18.0), mapY(-2.55) + 6);

    // Left: 19.77 m
    ctx.textAlign = 'right';
    ctx.textBaseline = 'middle';
    ctx.strokeText('19.77 m', mapX(-4.2) - 6, mapY(7.35));
    ctx.fillText('19.77 m', mapX(-4.2) - 6, mapY(7.35));

    // Right: 19.25 m (SOI PRID)
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';
    ctx.strokeText('19.25 m (SOI PRID)', mapX(38.0) + 8, mapY(7.15));
    ctx.fillText('19.25 m (SOI PRID)', mapX(38.0) + 8, mapY(7.15));

    // 2. Draw Grid Lines & Distinct CAD Bubbles
    const gridX = [
      { name: '1', x: 0.00 }, { name: '2', x: 0.50 }, { name: '3', x: 5.70 },
      { name: '4', x: 10.85 }, { name: '5', x: 12.20 }, { name: '6', x: 20.00 },
      { name: '7', x: 27.50 }, { name: '8', x: 29.45 }, { name: '9', x: 32.70 },
      { name: '10', x: 32.90 }
    ];

    const gridY = [
      { name: 'A', y: 12.40 }, { name: 'B', y: 5.20 }, { name: 'C', y: 3.50 },
      { name: 'D', y: 1.30 }, { name: 'E', y: 0.00 }
    ];

    const yTopGrid = mapY(18.2);
    const yBotGrid = mapY(-1.2);

    gridX.forEach(g => {
      const gx = mapX(g.x);
      ctx.strokeStyle = '#94a3b8';
      ctx.lineWidth = 1;
      ctx.setLineDash([4, 4]);
      ctx.beginPath();
      ctx.moveTo(gx, yTopGrid);
      ctx.lineTo(gx, yBotGrid);
      ctx.stroke();
      ctx.setLineDash([]);
    });

    // Top Bubbles
    const topBubbles = [
      { name: '1', x: 0.00, dy: 0 },
      { name: '3', x: 5.70, dy: 0 },
      { name: '4', x: 10.85, dy: 0 },
      { name: '5', x: 12.20, dy: 0 },
      { name: '6', x: 20.00, dy: 0 },
      { name: '7', x: 27.50, dy: 0 },
      { name: '8', x: 29.45, dy: 0 },
      { name: '9', x: 32.70, dy: 0 }
    ];

    const bubbleRadius = Math.max(8.5, Math.min(11.5, scale * 0.44));
    topBubbles.forEach(b => {
      const bx = mapX(b.x);
      const by = yTopGrid - bubbleRadius - 2 + (b.dy || 0);

      ctx.fillStyle = '#ffffff';
      ctx.strokeStyle = '#000000';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.arc(bx, by, bubbleRadius, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();

      ctx.fillStyle = '#0f172a';
      ctx.font = `bold ${Math.max(8, bubbleRadius * 0.9)}px Montserrat, Sarabun, sans-serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(b.name, bx, by);
    });

    // Top Dimension Lines
    const dimY1 = yTopGrid - bubbleRadius * 2 - 14;
    const dimY2 = dimY1 - 14;
    ctx.strokeStyle = '#0891b2';
    ctx.fillStyle = '#0891b2';
    ctx.lineWidth = 1;
    ctx.font = 'bold 9.5px Montserrat, Sarabun, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'bottom';

    const topSegments = [
      { x1: 0.00, x2: 0.50, val: '0.90' },
      { x1: 0.50, x2: 5.70, val: '5.20' },
      { x1: 5.70, x2: 10.85, val: '5.15' },
      { x1: 10.85, x2: 12.20, val: '1.35' },
      { x1: 12.20, x2: 20.00, val: '7.80' },
      { x1: 20.00, x2: 27.50, val: '7.50' },
      { x1: 27.50, x2: 29.45, val: '1.95' },
      { x1: 29.45, x2: 32.70, val: '3.25' }
    ];

    topSegments.forEach(seg => {
      const p1 = mapX(seg.x1);
      const p2 = mapX(seg.x2);
      ctx.beginPath();
      ctx.moveTo(p1, dimY1 + 3);
      ctx.lineTo(p1, dimY1 - 3);
      ctx.moveTo(p1, dimY1);
      ctx.lineTo(p2, dimY1);
      ctx.moveTo(p2, dimY1 + 3);
      ctx.lineTo(p2, dimY1 - 3);
      ctx.stroke();
      if (p2 - p1 > 14) {
        ctx.fillText(seg.val, (p1 + p2) / 2, dimY1 - 2);
      }
    });

    // Total Top Dimension: 32.90
    const startTop = mapX(0.00);
    const endTop = mapX(32.90);
    ctx.beginPath();
    ctx.moveTo(startTop, dimY2 + 3);
    ctx.lineTo(startTop, dimY2 - 3);
    ctx.moveTo(startTop, dimY2);
    ctx.lineTo(endTop, dimY2);
    ctx.moveTo(endTop, dimY2 + 3);
    ctx.lineTo(endTop, dimY2 - 3);
    ctx.stroke();
    ctx.fillText('32.90', (startTop + endTop) / 2, dimY2 - 2);

    // Horizontal Grids & Left Dimensions
    const xLeftGrid = mapX(-2.5);
    const xRightGrid = mapX(35.0);

    gridY.forEach(g => {
      const gy = mapY(g.y);
      ctx.strokeStyle = '#94a3b8';
      ctx.lineWidth = 1;
      ctx.setLineDash([4, 4]);
      ctx.beginPath();
      ctx.moveTo(xLeftGrid, gy);
      ctx.lineTo(xRightGrid, gy);
      ctx.stroke();
      ctx.setLineDash([]);
    });

    const dimX1 = xLeftGrid - 18;
    const dimX2 = dimX1 - 16;
    ctx.strokeStyle = '#0891b2';
    ctx.fillStyle = '#0891b2';
    ctx.lineWidth = 1;
    ctx.font = 'bold 9px Montserrat, Sarabun, sans-serif';
    ctx.textAlign = 'right';
    ctx.textBaseline = 'middle';

    const leftSegments = [
      { y1: 12.40, y2: 5.20, val: '7.20' },
      { y1: 5.20, y2: 3.50, val: '1.70' },
      { y1: 3.50, y2: 1.30, val: '2.20' },
      { y1: 1.30, y2: 0.00, val: '1.30' }
    ];

    leftSegments.forEach(seg => {
      const py1 = mapY(seg.y1);
      const py2 = mapY(seg.y2);
      ctx.beginPath();
      ctx.moveTo(dimX1 - 3, py1);
      ctx.lineTo(dimX1 + 3, py1);
      ctx.moveTo(dimX1, py1);
      ctx.lineTo(dimX1, py2);
      ctx.moveTo(dimX1 - 3, py2);
      ctx.lineTo(dimX1 + 3, py2);
      ctx.stroke();
      ctx.fillText(seg.val, dimX1 - 5, (py1 + py2) / 2);
    });

    // Total Left Dimension: 12.40
    const startLeftY = mapY(12.40);
    const endLeftY = mapY(0.00);
    ctx.beginPath();
    ctx.moveTo(dimX2 - 3, startLeftY);
    ctx.lineTo(dimX2 + 3, startLeftY);
    ctx.moveTo(dimX2, startLeftY);
    ctx.lineTo(dimX2, endLeftY);
    ctx.moveTo(dimX2 - 3, endLeftY);
    ctx.lineTo(dimX2 + 3, endLeftY);
    ctx.stroke();
    ctx.fillText('12.40', dimX2 - 5, (startLeftY + endLeftY) / 2);

    // North Symbol (Compass Rose at top right)
    const naX = mapX(34.8);
    const naY = mapY(18.5);
    ctx.save();
    ctx.beginPath();
    ctx.arc(naX, naY, 11, 0, Math.PI * 2);
    ctx.fillStyle = '#ffffff';
    ctx.fill();
    ctx.strokeStyle = '#0f172a';
    ctx.lineWidth = 1.2;
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(naX, naY - 10);
    ctx.lineTo(naX + 3.5, naY);
    ctx.lineTo(naX, naY - 2);
    ctx.lineTo(naX - 3.5, naY);
    ctx.closePath();
    ctx.fillStyle = '#dc2626';
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(naX, naY + 10);
    ctx.lineTo(naX + 3.5, naY);
    ctx.lineTo(naX, naY + 2);
    ctx.lineTo(naX - 3.5, naY);
    ctx.closePath();
    ctx.fillStyle = '#0f172a';
    ctx.fill();

    ctx.fillStyle = '#dc2626';
    ctx.font = 'bold 9px Montserrat, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('N', naX, naY - 13);
    ctx.restore();

    // 3. Draw All 93 Piles with I-beam shape & user colors (ภาพที่ 5: สีฟ้ากดวันนี้, สีเขียวกดแล้ว, สีขาวรอกด)
    const curDate = DailyReportState.date;
    const pilesDb = window.__PILES_DB__ || window.PILES_DATABASE || [];
    const progressRecs = getProgressRecords();
    const radius = Math.max(7.8, Math.min(10.8, scale * 0.42));
    const fontSize = Math.max(7.5, Math.min(9.8, radius * 0.95));

    pilesDb.forEach(p => {
      const cx = mapX(p.x);
      const cy = mapY(p.y);
      const rec = progressRecs[p.no];
      const isDriven = rec && rec.status === 'driven';
      const pileDate = rec ? rec.date : null;
      const isToday = isDriven && pileDate === curDate;
      const isPastDriven = isDriven && (!pileDate || pileDate < curDate);

      // Radial glow if driven today
      if (isToday) {
        ctx.save();
        const glowGrad = ctx.createRadialGradient(cx, cy, radius * 0.3, cx, cy, radius + 12);
        glowGrad.addColorStop(0, 'rgba(56, 189, 248, 0.95)');
        glowGrad.addColorStop(0.45, 'rgba(14, 165, 233, 0.5)');
        glowGrad.addColorStop(1, 'rgba(2, 132, 199, 0)');
        ctx.fillStyle = glowGrad;
        ctx.beginPath();
        ctx.arc(cx, cy, radius + 12, 0, Math.PI * 2);
        ctx.fill();

        ctx.strokeStyle = '#00f0ff';
        ctx.lineWidth = 2.4;
        ctx.beginPath();
        ctx.arc(cx, cy, radius + 3, 0, Math.PI * 2);
        ctx.stroke();
        ctx.restore();
      }

      let fillColor = '#ffffff';
      let strokeColor = '#000000';
      let strokeWidth = 1.4;
      let textColor = '#0f172a';

      if (isToday) {
        fillColor = '#0284c7'; // Sky Blue (สีฟ้ากดวันนี้)
        strokeColor = '#0369a1';
        strokeWidth = 2.0;
        textColor = '#ffffff';
      } else if (isPastDriven) {
        fillColor = '#10b981'; // Emerald Green (สีเขียวกดแล้ว)
        strokeColor = '#064e3b';
        strokeWidth = 1.8;
        textColor = '#ffffff';
      }

      ctx.fillStyle = fillColor;
      ctx.strokeStyle = strokeColor;
      ctx.lineWidth = strokeWidth;

      ctx.beginPath();
      ctx.arc(cx, cy, radius, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();

      // If waiting, draw small I-beam icon inside
      if (!isToday && !isPastDriven) {
        const iw = radius * 0.7;
        const ih = radius * 0.9;
        ctx.strokeStyle = '#94a3b8';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(cx - iw / 2, cy - ih / 2);
        ctx.lineTo(cx + iw / 2, cy - ih / 2);
        ctx.moveTo(cx, cy - ih / 2);
        ctx.lineTo(cx, cy + ih / 2);
        ctx.moveTo(cx - iw / 2, cy + ih / 2);
        ctx.lineTo(cx + iw / 2, cy + ih / 2);
        ctx.stroke();
      }

      ctx.fillStyle = textColor;
      ctx.font = `bold ${fontSize}px Montserrat, Sarabun, sans-serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(p.no.toString(), cx, cy);
    });
  }


